fig,axes=plt.subplots(1,2,figsize=(11,4),layout='constrained');x=np.arange(2)
for j,v in enumerate(variants):axes[0].bar(x+(j-1)*.24,[a[v]['edge_subsets'][k]['recovered']/a[v]['edge_subsets'][k]['total']*100 for k in ('dashed','branch')],width=.24,label=names[j],color=colors[j])
axes[0].set_xticks(x,['Dashed signals (n=10)','Branched adjacency (n=16)']);axes[0].set_ylim(0,105);axes[0].set_ylabel('Recall %');axes[0].legend(fontsize=8);axes[0].set_title('Subsets are correlated, not independent projects')
