for j,v in enumerate(('v8','v9')):axes[1].bar(x+(j-.5)*.32,[s['variants'][v]['scores']['connections']['recall']*100 for s in r['sheets']],width=.32,label=v,color=colors[0 if j==0 else 2])
axes[1].set_xticks(x,['Winkler142','Winkler150','NEWPCC2','WEWPCC7'],rotation=10);axes[1].set_ylim(0,105);axes[1].set_ylabel('Connection recall %');axes[1].set_title('Per-page small-ROI results');axes[1].legend()
