for j,v in enumerate(('v8','v9')):
 for ax,m in zip(axes,('recall','f1')):ax.bar(x+(j-.5)*.32,[reg['aggregate']['group'][g][v]['connections'][m]*100 for g in groups],width=.32,label=v,color=colors[0 if j==0 else 2]);ax.set_xticks(x,['Historical OPEN100 6','Historical synthetic8']);ax.set_ylim(0,100);ax.set_title('Historical connection '+m);ax.set_ylabel('%');ax.legend()
